import React, { useEffect, useState } from "react";
import "../styles/subscriptions.css";

function Subscriptions() {
  const [channels, setChannels] = useState([]);
  const [selectedChannel, setSelectedChannel] = useState(null);
  const [articles, setArticles] = useState([]);
  const [polls, setPolls] = useState([]);
  const [error, setError] = useState(null);

  const token = localStorage.getItem("token");

  // Завантаження каналів
  useEffect(() => {
    fetch("/api/channels/", {
      headers: { Authorization: `Bearer ${token}` },
    })
      .then((res) => res.json())
      .then((data) => setChannels(data))
      .catch((err) => setError("Помилка завантаження каналів"));
  }, [token]);

  // Завантаження контенту (статті + опитування)
  useEffect(() => {
    if (!selectedChannel) return;

    Promise.all([
      fetch(`/api/articles/?channel=${selectedChannel.id}`, {
        headers: { Authorization: `Bearer ${token}` },
      }).then((res) => res.json()),
      fetch(`/api/polls/?channel=${selectedChannel.id}`, {
        headers: { Authorization: `Bearer ${token}` },
      }).then((res) => res.json()),
    ])
      .then(([articlesData, pollsData]) => {
        setArticles(articlesData);
        setPolls(pollsData);
      })
      .catch(() => setError("Помилка завантаження контенту"));
  }, [selectedChannel, token]);

  // Об’єднання контенту за часом
  const combinedContent = [...articles.map(a => ({ ...a, type: "article" })),
                           ...polls.map(p => ({ ...p, type: "poll" }))];

  combinedContent.sort(
    (a, b) => new Date(b.created_at) - new Date(a.created_at)
  );

  const handleVote = async (pollId, choiceId) => {
    try {
      const response = await fetch(`/api/polls/${pollId}/vote/${choiceId}/`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${token}`,
        },
      });

      if (!response.ok) {
        throw new Error("Помилка при голосуванні");
      }

      // Оновлення даних після голосування
      const updatedPoll = await response.json();
      setPolls((prevPolls) =>
        prevPolls.map((p) => (p.id === pollId ? updatedPoll : p))
      );
    } catch (error) {
      console.error(error);
      setError("Не вдалося проголосувати");
    }
  };

  return (
    <div className="subscriptions">
      <h2>Підписки</h2>

      {error && <p className="error">{error}</p>}

      <div className="channel-list">
        {channels.map((ch) => (
          <button
            key={ch.id}
            className={`channel-btn ${
              selectedChannel?.id === ch.id ? "active" : ""
            }`}
            onClick={() => setSelectedChannel(ch)}
          >
            {ch.name}
          </button>
        ))}
      </div>

      {selectedChannel && (
        <div className="content-list">
          <h3>Контент каналу: {selectedChannel.name}</h3>

          {combinedContent.length === 0 && <p>Немає контенту.</p>}

          {combinedContent.map((item) =>
            item.type === "article" ? (
              <div key={`article-${item.id}`} className="article-card">
                <h4>{item.title}</h4>
                <p>{item.content}</p>
                <small>🕓 {new Date(item.created_at).toLocaleString()}</small>
              </div>
            ) : (
              <div key={`poll-${item.id}`} className="poll-card">
                <h4>🗳️ {item.question}</h4>
                {item.choices.map((choice) => (
                  <div key={choice.id} className="poll-choice">
                    <button
                      onClick={() => handleVote(item.id, choice.id)}
                      className="vote-btn"
                    >
                      Проголосувати
                    </button>
                    <span>
                      {choice.text} — <b>{choice.votes}</b> голосів
                    </span>
                  </div>
                ))}
                <small>🕓 {new Date(item.created_at).toLocaleString()}</small>
              </div>
            )
          )}
        </div>
      )}
    </div>
  );
}

export default Subscriptions;
